  `category_id` int NOT NULL,
  `average_score` double DEFAULT '0',
  `status` enum('PASS','FAIL') DEFAULT 'FAIL',
  `graded_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `averageScore` double DEFAULT NULL,
  `gradedAt` datetime(6) DEFAULT NULL,
  PRIMARY KEY (`category_grade_id`),
  UNIQUE KEY `student_id` (`student_id`,`class_id`,`category_id`),
  UNIQUE KEY `UKn2b0lim40rawiggsimrjmmjud` (`student_id`,`class_id`,`category_id`),
  KEY `fk_cg_class` (`class_id`),
  KEY `fk_cg_category` (`category_id`),
  CONSTRAINT `fk_cg_category` FOREIGN KEY (`category_id`) REFERENCES `course_categories` (`category_id`),
  CONSTRAINT `fk_cg_class` FOREIGN KEY (`class_id`) REFERENCES `classes` (`class_id`),
  CONSTRAINT `fk_cg_student` FOREIGN KEY (`student_id`) REFERENCES `users` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
