INSERT INTO `exam_questions` VALUES (212,8,'Which is a benefit of using AI for office productivity?','MCQ',25,'[\"AI automatically replaces all human decision-making\", \"AI can summarize documents and automate reporting\", \"AI removes all human errors completely\", \"AI eliminates the need for teamwork\"]','[\"AI can summarize documents and automate reporting\"]',NULL,1,NULL,NULL),(213,8,'Which prompt type is best for productivity tasks such as writing emails?','MCQ',25,'[\"To memorize all HTML tags\", \"A blueprint/template for creating objects\", \"A variable storing object data\", \"K-means Clustering\"]','[\"To memorize all HTML tags\"]',NULL,2,NULL,NULL),(214,8,'Overfitting occurs when:','MCQ',25,'[\"The model learns the perfect general patterns\", \"The model learns noise and performs poorly on new data\", \"The model performs well on unseen data\", \"The dataset is too small to train\"]','[\"The model learns noise and performs poorly on new data\"]',NULL,3,NULL,NULL),(215,8,'Which of the following is an example of Deep Learning?','MCQ',25,'[\"Decision Trees\", \"Linear Regression\", \"Convolutional Neural Networks (CNN)\", \"K-means Clustering\"]','[\"Convolutional Neural Networks (CNN)\"]',NULL,4,NULL,NULL),(260,11,'(Ví dụ) 1 + 1 = ?','MCQ',25,'[\"1\", \"2\", \"3\", \"4\"]','[\"2\"]','10',1,'',NULL),(261,11,'(Ví dụ) Thủ đô VN?','SHORT_ANSWER',25,NULL,NULL,'5',2,'',NULL),(262,11,'(Ví dụ) Chọn số chẵn','MULTI',25,'[\"2\", \"3\", \"4\", \"5\"]','[\"2\", \"4\"]','15',3,'',NULL),(263,11,'(Ví dụ) Trái đất tròn?','TRUE_FALSE',25,NULL,'[\"True\"]','5',4,'',NULL),(265,12,'Để người dùng bắt buộc phải nhập dữ liệu vào ô input trước khi gửi, ta thêm thuộc tính gì?','MCQ',50,'[\"validate\", \"important\", \"mandatory\", \"required\"]','[\"required\"]',NULL,2,NULL,NULL),(266,12,'Thuộc tính nào giúp hiển thị gợi ý mờ trong ô input (ví dụ: \"Nhập email của bạn\")?','MCQ',50,'[\"value\", \"placeholder\", \"label\", \"name\"]','[\"placeholder\"]',NULL,3,NULL,NULL),(267,13,'1+1 = 2','TRUE_FALSE',100,'[\"\", \"\", \"\", \"\"]','[\"True\"]',NULL,1,NULL,NULL),(268,14,'1 + 1 = 2','TRUE_FALSE',100,'[\"\", \"\", \"\", \"\"]','[\"True\"]',NULL,1,NULL,NULL),(269,15,'2 + 2 = 4','TRUE_FALSE',100,'[\"\", \"\", \"\", \"\"]','[\"True\"]',NULL,1,NULL,NULL),(273,17,'Garbage Collection trong JS làm nhiệm vụ gì?','MCQ',100,'[\"Sắp xếp lại code cho đẹp.\", \"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\", \"Tìm lỗi logic.\", \"None\"]','[\"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\"]',NULL,1,NULL,NULL),(274,2,'Garbage Collection trong JS làm nhiệm vụ gì?','MCQ',25,'[\"Sắp xếp lại code cho đẹp.\", \"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\", \"Tìm lỗi logic.\", \"None\"]','[\"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\"]',NULL,1,NULL,NULL),(275,2,'Ưu điểm của Static Typing (Kiểu tĩnh) so với Dynamic Typing (Kiểu động) là gì?','MCQ',25,'[\"Viết code nhanh hơn.\", \"Phát hiện lỗi sai kiểu dữ liệu ngay khi viết code/biên dịch.\", \"Không cần khai báo kiểu.\"]','[\"Phát hiện lỗi sai kiểu dữ liệu ngay khi viết code/biên dịch.\"]',NULL,2,NULL,NULL),(276,2,'Khi truyền một Object vào hàm, nếu thay đổi thuộc tính của nó trong hàm thì Object gốc bên ngoài có bị đổi không?','MCQ',25,'[\"Có (Do tham chiếu).\", \"Không (Do tham trị).\", \"Không do nào hết\"]','[\"Có (Do tham chiếu).\"]',NULL,3,NULL,NULL),(277,2,'JSON.stringify() dùng để làm gì?','MCQ',25,'[\"Chuyển chuỗi JSON thành Object.\", \"Chuyển Object thành chuỗi JSON.\", \"Xóa Object.\", \"None\"]','[\"Chuyển Object thành chuỗi JSON.\"]',NULL,4,NULL,NULL),(278,18,'The template string is indicated with a dollar sign and curly brackets (${expression}) inside the backtick symbol.','MCQ',14.29,'[\"A\", \"B\", \"C\", \"D\"]','[\"A\"]',NULL,1,NULL,NULL),(279,18,'Garbage Collection trong JS làm nhiệm vụ gì?','MCQ',14.29,'[\"Sắp xếp lại code cho đẹp.\", \"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\", \"Tìm lỗi logic.\", \"None\"]','[\"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\"]',NULL,2,NULL,NULL),(280,18,'Ưu điểm của Static Typing (Kiểu tĩnh) so với Dynamic Typing (Kiểu động) là gì?','MCQ',14.29,'[\"Viết code nhanh hơn.\", \"Phát hiện lỗi sai kiểu dữ liệu ngay khi viết code/biên dịch.\", \"Không cần khai báo kiểu.\"]','[\"Phát hiện lỗi sai kiểu dữ liệu ngay khi viết code/biên dịch.\"]',NULL,3,NULL,NULL),(281,18,'Khi truyền một Object vào hàm, nếu thay đổi thuộc tính của nó trong hàm thì Object gốc bên ngoài có bị đổi không?','MCQ',14.29,'[\"Có (Do tham chiếu).\", \"Không (Do tham trị).\", \"Không do nào hết\"]','[\"Có (Do tham chiếu).\"]',NULL,4,NULL,NULL),(282,18,'Đề bài: Viết một hàm nhận vào một mảng số nguyên arr. Hãy tìm và trả về giá trị lớn nhất trong mảng đó. Yêu cầu đầu ra: Trả về một số nguyên int là giá trị lớn nhất tìm được.','CODING',42.86,'[\"\", \"\", \"\", \"\"]',NULL,'java',5,'public class Solution {\r\n    public int findMax(int[] arr) {\r\n        // Viết code của bạn ở đây\r\n        // Ví dụ: arr = [1, 5, 3] -> return 5\r\n        return 0; \r\n    }\r\n}','[{\"input\": \"[1, 5, 3, 9, 2]\", \"isHidden\": false, \"expectedOutput\": \"9\"}, {\"input\": \"[-10, -5, -2, -20]\", \"isHidden\": false, \"expectedOutput\": \"-2\"}, {\"input\": \"[100]\", \"isHidden\": false, \"expectedOutput\": \"100\"}]');
