INSERT INTO `question_banks` VALUES (35,'[\"Decision Trees\", \"Linear Regression\", \"Convolutional Neural Networks (CNN)\", \"K-means Clustering\"]','[\"Convolutional Neural Networks (CNN)\"]','2025-11-28 13:47:14.131187','EASY',NULL,1,'Which of the following is an example of Deep Learning?','MCQ','ACTIVE','2025-11-28 13:47:14.131187',1),(36,'[\"The model learns the perfect general patterns\", \"The model learns noise and performs poorly on new data\", \"The model performs well on unseen data\", \"The dataset is too small to train\"]','[\"The model learns noise and performs poorly on new data\"]','2025-11-28 13:47:15.310870','EASY',NULL,1,'Overfitting occurs when:','MCQ','ACTIVE','2025-11-28 13:47:15.310870',1),(37,'[\"To memorize all HTML tags\", \"A blueprint/template for creating objects\", \"A variable storing object data\", \"K-means Clustering\"]','[\"To memorize all HTML tags\"]','2025-11-28 13:56:46.545239','EASY',NULL,1,'Which prompt type is best for productivity tasks such as writing emails?','MCQ','ACTIVE','2025-11-28 13:56:46.545239',1),(38,'[\"AI automatically replaces all human decision-making\", \"AI can summarize documents and automate reporting\", \"AI removes all human errors completely\", \"AI eliminates the need for teamwork\"]','[\"AI can summarize documents and automate reporting\"]','2025-11-28 13:56:47.869193','EASY',NULL,1,'Which is a benefit of using AI for office productivity?','MCQ','ACTIVE','2025-11-28 13:56:47.869193',1),(39,'[\"<doctype html>\", \"<!DOCTYPE html>\", \"<html5>\", \"<!DOCTYPE html5>\"]','[\"<!DOCTYPE html>\"]','2025-12-02 14:55:41.449449','EASY',NULL,1,'Đâu là khai báo chuẩn cho văn bản HTML5?','MCQ','ACTIVE','2025-12-02 14:55:41.449449',1),(40,'[\"<head>\", \"<h6>\", \"<h1>\", \"<header>\"]','[\"<h1>\"]','2025-12-02 14:55:42.813008','EASY',NULL,1,'Thẻ nào sau đây dùng để tạo tiêu đề lớn nhất và quan trọng nhất trang?','MCQ','ACTIVE','2025-12-02 14:55:42.813008',1),(41,'[\"Tag (Thẻ)\", \"(Thuộc tính)\", \"Element (Phần tử)\", \"Content (Nội dung)\"]','[\"(Thuộc tính)\"]','2025-12-02 14:55:44.038994','EASY',NULL,1,'Trong thẻ <p title=\"Hello\">, từ title được gọi là gì?','MCQ','ACTIVE','2025-12-02 14:55:44.038994',1),(42,'[\"target=\\\"_new\\\"\", \"target=\\\"_blank\\\"\", \"target=\\\"_self\\\"\", \"window=\\\"new\\\"\"]','[\"target=\\\"_blank\\\"\"]','2025-12-02 14:59:27.752194','EASY',NULL,1,'Để mở một liên kết trong tab mới, ta dùng thuộc tính nào trong thẻ <a>?','MCQ','ACTIVE','2025-12-02 14:59:27.752194',1),(43,'[\"href và alt\", \"link và src\", \"src và alt\", \"source và title\"]','[\"src và alt\"]','2025-12-02 14:59:28.870784','EASY',NULL,1,'Thuộc tính nào là bắt buộc đối với thẻ <img>?','MCQ','ACTIVE','2025-12-02 14:59:28.870784',1),(44,'[\"1, 2, 3...\", \"A, B, C...\", \"Chấm tròn (bullet points)\", \"Số La Mã (I, II...)\"]','[\"Chấm tròn (bullet points)\"]','2025-12-02 14:59:29.996252','EASY',NULL,1,'Đoạn code <ul> <li>A</li> <li>B</li> </ul> sẽ hiển thị danh sách dạng gì?','MCQ','ACTIVE','2025-12-02 14:59:29.996252',1),(45,'[\"rowspan=\\\"2\\\"\", \"merge=\\\"2\\\"\", \"colspan=\\\"2\\\"\", \"combine=\\\"2\\\"\"]','[\"colspan=\\\"2\\\"\"]','2025-12-02 15:03:43.539209','EASY',NULL,1,'Để gộp 2 cột thành 1 cột trong bảng, ta dùng thuộc tính nào?','MCQ','ACTIVE','2025-12-02 15:03:43.539209',1),(46,'[\"value\", \"placeholder\", \"label\", \"name\"]','[\"placeholder\"]','2025-12-02 15:03:44.722153','EASY',NULL,1,'Thuộc tính nào giúp hiển thị gợi ý mờ trong ô input (ví dụ: \"Nhập email của bạn\")?','MCQ','ACTIVE','2025-12-02 15:03:44.722153',1),(47,'[\"validate\", \"important\", \"mandatory\", \"required\"]','[\"required\"]','2025-12-02 15:03:45.953610','EASY',NULL,1,'Để người dùng bắt buộc phải nhập dữ liệu vào ô input trước khi gửi, ta thêm thuộc tính gì?','MCQ','ACTIVE','2025-12-02 15:03:45.953610',1),(48,'[\"colspan\", \"cellspacing\", \"rowspan\", \"merge\"]','[\"colspan\", \"rowspan\"]','2025-12-02 15:03:47.109083','EASY',NULL,1,'Để thực hiện kỹ thuật gộp ô trong bảng (<table>), chúng ta sử dụng 2 thuộc tính nào sau đây? (Chọn 2 đáp án đúng)','MCQ','ACTIVE','2025-12-02 15:03:47.109083',1),(49,'[\"20 (Number)\", \"\\\"1010\\\" (String)\", \"Syntax Error\", \"NaN\"]','[\"\\\"1010\\\" (String)\"]','2025-12-03 16:21:25.393171','EASY',NULL,1,'Cú pháp & Biến Câu 1: Trong JavaScript, kết quả của phép tính 10 + \"10\" là gì?','MCQ','ACTIVE','2025-12-03 16:21:25.393171',1),(50,'[\"$money\", \"1stPlace\", \"full-name\", \"_privateVar\"]','[\"1stPlace\", \"full-name\"]','2025-12-03 16:21:26.695141','EASY',NULL,1,'(Chọn 2 đáp án): Những tên biến nào sau đây là KHÔNG hợp lệ (Gây lỗi cú pháp)?','MCQ','ACTIVE','2025-12-03 16:21:26.695141',1),(51,'[\"for\", \"while\", \"do...while\", \"forEach\"]','[\"do...while\"]','2025-12-03 16:21:27.777696','EASY',NULL,1,'Logic & Vòng lặp Câu 3: Vòng lặp nào sẽ thực hiện khối lệnh ít nhất một lần ngay cả khi điều kiện sai ngay từ đầu?','MCQ','ACTIVE','2025-12-03 16:21:27.777696',1),(52,'[\"=== chỉ so sánh giá trị.\", \"=== so sánh cả giá trị và kiểu dữ liệu.\", \"=== dùng cho số, == dùng cho chuỗi.\", \"Không khác nhau.\"]','[\"=== so sánh cả giá trị và kiểu dữ liệu.\"]','2025-12-03 16:21:28.844330','EASY',NULL,1,'Toán tử === khác == ở điểm nào? A. . B. C. === dùng cho số, D.','MCQ','ACTIVE','2025-12-03 16:21:28.844330',1),(53,'[\"ên biến vô nghĩa (x, y, z, temp).\", \"Một hàm dài quá 100 dòng.\", \"Sử dụng Comment để giải thích code phức tạp thay vì viết code đơn giản.\", \"Sử dụng tên biến Tiếng Anh chuẩn.\"]','[\"ên biến vô nghĩa (x, y, z, temp).\", \"Một hàm dài quá 100 dòng.\", \"Sử dụng Comment để giải thích code phức tạp thay vì viết code đơn giản.\"]','2025-12-03 16:21:29.884299','EASY',NULL,1,'(Chọn 3 đáp án): Đâu là những dấu hiệu của \"Code thối\" (Bad Smell/Messy Code)?','MCQ','ACTIVE','2025-12-03 16:21:29.884299',1),(54,'[\"while\", \"for\", \"do...while\", \"if...else\"]','[\"for\"]','2025-12-03 16:36:43.127715','EASY',NULL,1,'Nếu biết trước chính xác số lần cần lặp lại một hành động (ví dụ: chạy từ 1 đến 100), ta nên dùng vòng lặp nào là tối ưu nhất?','MCQ','ACTIVE','2025-12-03 16:36:43.127715',1),(55,'[\"1\", \"0\", \"-1\", \"Tùy ngôn ngữ\"]','[\"0\"]','2025-12-03 16:36:44.312108','EASY',NULL,1,'Trong một mảng (Array), phần tử đầu tiên có chỉ số (index) là bao nhiêu?','MCQ','ACTIVE','2025-12-03 16:36:44.312108',1),(56,'[\"Có thể được truy cập từ bất kỳ đâu trong chương trình.\", \"Sẽ bị hủy (xóa khỏi bộ nhớ) sau khi hàm chạy xong.\", \"Luôn giữ giá trị cũ cho lần chạy hàm tiếp theo.\", \"Làm tốn nhiều bộ nhớ RAM hơn biến toàn cục.\"]','[\"Sẽ bị hủy (xóa khỏi bộ nhớ) sau khi hàm chạy xong.\"]','2025-12-03 16:36:45.254981','EASY',NULL,1,'Biến được khai báo bên trong một hàm (Local Variable) có đặc điểm gì?','MCQ','ACTIVE','2025-12-03 16:36:45.254981',1),(57,'[\"Khi điều kiện lặp luôn luôn SAI.\", \"Khi điều kiện lặp luôn luôn ĐÚNG và không có lệnh thoát.\", \"Khi dùng vòng lặp for.\", \"Khi máy tính bị virus.\"]','[\"Khi điều kiện lặp luôn luôn ĐÚNG và không có lệnh thoát.\"]','2025-12-03 16:36:46.179177','EASY',NULL,1,'Vòng lặp vô tận (Infinite Loop) xảy ra khi nào?','MCQ','ACTIVE','2025-12-03 16:36:46.179177',1),(58,'[\"Do Repeat Yourself (Hãy lặp lại code của bạn).\", \"Don\'t Repeat Yourself (Đừng lặp lại chính mình).\", \"Data Retrieval Yet (Dữ liệu chưa lấy được).\", \"Debug Run Yield (Chạy gỡ lỗi).\"]','[\"Don\'t Repeat Yourself (Đừng lặp lại chính mình).\"]','2025-12-03 16:41:55.667194','EASY',NULL,1,'Nguyên tắc DRY trong lập trình viết tắt của từ gì?','MCQ','ACTIVE','2025-12-03 16:41:55.667194',1),(59,'[\"StudentScore\", \"student_score\", \"studentScore\", \"STUDENT_SCORE\"]','[\"studentScore\"]','2025-12-03 16:41:56.730777','EASY',NULL,1,'Quy tắc đặt tên kiểu camelCase (Lạc đà) nào sau đây là đúng?','MCQ','ACTIVE','2025-12-03 16:41:56.730777',1),(60,'[\"Breakpoint\", \"Stoppoint\", \"Pause function\", \"console.log\"]','[\"Breakpoint\"]','2025-12-03 16:41:57.798367','EASY',NULL,1,'Để tạm dừng chương trình tại một dòng cụ thể nhằm kiểm tra giá trị của biến khi đang Debug, ta sử dụng công cụ gì?','MCQ','ACTIVE','2025-12-03 16:41:57.798367',1),(61,'[\"Để giải thích code hoạt động \\\"như thế nào\\\" (dịch code sang tiếng Việt).\", \"Để làm code trông dài hơn và chuyên nghiệp hơn.\", \"Để giải thích \\\"tại sao\\\" lại viết logic như vậy (nghiệp vụ, lý do).\", \"Để máy tính chạy nhanh hơn.\"]','[\"Để giải thích \\\"tại sao\\\" lại viết logic như vậy (nghiệp vụ, lý do).\"]','2025-12-03 16:41:58.881642','EASY',NULL,1,'Mục đích chính của việc viết Comment (Chú thích) trong code là gì?','MCQ','ACTIVE','2025-12-03 16:41:58.881642',1),(62,'[\"Viết code ngay -> Sửa lỗi -> Đọc đề.\", \"Đọc đề -> Viết code -> Vẽ lưu đồ.\", \"Hiểu vấn đề -> Chia nhỏ bài toán -> Vẽ thuật toán -> Viết code.\", \"Tìm code trên mạng copy -> Chạy thử.\"]','[\"Hiểu vấn đề -> Chia nhỏ bài toán -> Vẽ thuật toán -> Viết code.\"]','2025-12-03 16:42:00.099381','EASY',NULL,1,'Đâu là các bước đúng trong quy trình giải quyết vấn đề (Problem Solving)?','MCQ','ACTIVE','2025-12-03 16:42:00.099381',1),(63,'[\"var\", \"let\", \"const\", \"static\"]','[\"const\"]','2025-12-03 21:28:03.858693','EASY',NULL,1,'Từ khóa nào dùng để khai báo hằng số (không thể gán lại giá trị)?','MCQ','ACTIVE','2025-12-03 21:28:03.858693',1),(64,'[\"Có\", \"Không\", \"(Do Block Scope)\"]','[\"Không\"]','2025-12-03 21:28:07.415214','EASY',NULL,1,'Biến được khai báo bên trong khối if { ... } bằng từ khóa let có thể truy cập được ở ngoài khối đó không? A. B.','MCQ','ACTIVE','2025-12-03 21:28:07.415214',1),(65,'[\"$price\", \"_private\", \"2ndPlace\", \"myVar\"]','[\"2ndPlace\"]','2025-12-03 21:28:08.893623','EASY',NULL,1,'Tên biến nào sau đây sai quy tắc?','MCQ','ACTIVE','2025-12-03 21:28:08.893623',1),(66,'[\"Đặt tên cho biến\", \"Gán giá trị đầu tiên cho biến.\", \"Xóa biến.\"]','[\"Gán giá trị đầu tiên cho biến.\"]','2025-12-03 21:28:13.144763','EASY',NULL,1,'Khởi tạo biến là gì? A.. B.  C.','MCQ','ACTIVE','2025-12-03 21:28:13.144763',1),(67,'[\"undefined\", \"ReferenceError (Lỗi vùng chết TDZ)\", \"SyntaxError\", \"None\"]','[\"ReferenceError (Lỗi vùng chết TDZ)\"]','2025-12-03 21:28:14.663726','EASY',NULL,1,'Trong JS, nếu dùng biến let trước khi khai báo sẽ gặp lỗi gì? A. B.  C.','MCQ','ACTIVE','2025-12-03 21:28:14.663726',1),(68,'[\"text\", \"string\", \"object\"]','[\"string\"]','2025-12-03 21:32:54.837010','EASY',NULL,1,'Kết quả của typeof \"Hello\" là gì?','MCQ','ACTIVE','2025-12-03 21:32:54.837010',1),(69,'[\"Boolean\", \"Object\", \"Number\", \"String\"]','[\"Object\"]','2025-12-03 21:33:01.208305','EASY',NULL,1,'Kiểu dữ liệu nào sau đây là kiểu Tham chiếu (Reference)?','MCQ','ACTIVE','2025-12-03 21:33:01.208305',1),(70,'[\"0\", \"1\", \"2\", \"-1\"]','[\"0\"]','2025-12-03 21:33:03.107378','EASY',NULL,1,'Mảng trong JS bắt đầu đánh chỉ số từ mấy?','MCQ','ACTIVE','2025-12-03 21:33:03.107378',1),(71,'[\"30\", \"\\\"1020\\\"\", \"NaN\", \"20\"]','[\"\\\"1020\\\"\"]','2025-12-03 21:33:05.007274','EASY',NULL,1,'10 + \"20\" sẽ cho kết quả là?','MCQ','ACTIVE','2025-12-03 21:33:05.007274',1),(72,'[\"Ngoặc đơn \' \'\", \"Ngoặc kép \\\" \\\"\", \"Backticks ` `\", \"{}\"]','[\"Backticks ` `\"]','2025-12-03 21:33:08.875691','EASY',NULL,1,'Để tạo chuỗi chứa biến ${name}, ta dùng dấu gì bao quanh? A.  B.  C.','MCQ','ACTIVE','2025-12-03 21:33:08.875691',1),(73,'[\"0\", \"[ ]\", \"undefined\", \"-1\"]','[\"undefined\"]','2025-12-03 21:43:48.803889','EASY',NULL,1,'Giá trị nào sau đây là Falsy?','MCQ','ACTIVE','2025-12-03 21:43:48.803889',1),(74,'[\"Chuyển chuỗi JSON thành Object.\", \"Chuyển Object thành chuỗi JSON.\", \"Xóa Object.\", \"None\"]','[\"Chuyển Object thành chuỗi JSON.\"]','2025-12-03 21:43:52.596317','EASY',NULL,1,'JSON.stringify() dùng để làm gì?','MCQ','ACTIVE','2025-12-03 21:43:52.596317',1),(75,'[\"Có (Do tham chiếu).\", \"Không (Do tham trị).\", \"Không do nào hết\"]','[\"Có (Do tham chiếu).\"]','2025-12-03 21:43:55.068765','EASY',NULL,1,'Khi truyền một Object vào hàm, nếu thay đổi thuộc tính của nó trong hàm thì Object gốc bên ngoài có bị đổi không?','MCQ','ACTIVE','2025-12-03 21:43:55.068765',1),(76,'[\"Viết code nhanh hơn.\", \"Phát hiện lỗi sai kiểu dữ liệu ngay khi viết code/biên dịch.\", \"Không cần khai báo kiểu.\"]','[\"Phát hiện lỗi sai kiểu dữ liệu ngay khi viết code/biên dịch.\"]','2025-12-03 21:43:58.446686','EASY',NULL,1,'Ưu điểm của Static Typing (Kiểu tĩnh) so với Dynamic Typing (Kiểu động) là gì?','MCQ','ACTIVE','2025-12-03 21:43:58.446686',1),(77,'[\"Sắp xếp lại code cho đẹp.\", \"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\", \"Tìm lỗi logic.\", \"None\"]','[\"Tự động xóa các biến không còn được sử dụng để giải phóng RAM.\"]','2025-12-03 21:43:59.429365','EASY',NULL,1,'Garbage Collection trong JS làm nhiệm vụ gì?','MCQ','ACTIVE','2025-12-03 21:43:59.429365',1),(78,'[\"A\", \"B\", \"C\", \"D\"]','[\"A\"]','2025-12-04 16:11:30.801602','EASY',NULL,1,'The template string is indicated with a dollar sign and curly brackets (${expression}) inside the backtick symbol.','MCQ','ACTIVE','2025-12-04 16:11:30.801610',1),(79,'[\"A\", \"B\", \"C\", \"D\"]','[\"B\"]','2025-12-04 16:11:31.132656','EASY',NULL,1,'Câu hỏi 2','MCQ','ACTIVE','2025-12-04 16:11:31.132665',1);
